const baseRefresh=refresh,baseInspector=inspector,baseTimeline=timeline,baseAdd=add,baseValidate=validate,basePos=pos,basePalette=palette;

function setup(){const e=level.environment??={floor:'Corneria',backdrop:'Corneria',mode:'Land rail',boss:'Granga'};$('environment').innerHTML=`<label>Floor / terrain</label><select data-env="floor">${options(stages.map(s=>[s,s]),e.floor)}</select><label>Backdrop</label><select data-env="backdrop">${options(stages.map(s=>[s,s]),e.backdrop)}</select><label>Level type</label><select data-env="mode">${options(['Land rail','Space rail','All range'].map(s=>[s,s]),e.mode)}</select><label>Existing boss</label><select data-env="boss">${options(['Granga','Carrier','Meteo Crusher','Shogun','Saucerer','Bacoon','Gore','Sarumarine','Spyborg','Goras','Mechbeth','Gorgon','Andross'].map(s=>[s,s]),e.boss)}</select><div class="tip">Playtest lets you choose a matching space or land stage in Starship. Your Floor / terrain and Backdrop choices are used in game. The selected stage supplies its intro and ending.</div>`;$('environment').querySelectorAll('[data-env]').forEach(el=>el.onchange=()=>{stash();e[el.dataset.env]=el.value;refresh()})}

