function bindFields(o){$('inspector').querySelectorAll('[data-key]').forEach(el=>el.onchange=()=>{if(el.type==='number'&&!el.checkValidity()){el.reportValidity();return}stash();let k=el.dataset.key;o[k]=['text','type','targetWave'].includes(k)?el.value:Number(el.value);refresh()})}

add=function(id){if(tab==='enemy'){baseAdd(id);let o=current(),d=defaults(o);o.hp=d.hp;o.points=d.points;refresh();return}if(tab==='scenery'){baseAdd(id);return}stash();if(tab==='items'){let o={id:uid(),time:time,item:id,x:0,y:350,z:5000};level.items.push(o);selected={kind:'item',id:o.id};setTime(o.time)}else{let o={id:uid(),time:time,type:id,speaker:id==='supply'?90:30,line:-1,text:id==='supply'?'Supplies incoming!':'Watch out, Fox!',ship:1,shoot:0,x:-700,y:450,z:5000,duration:8,width:600,height:500,targetWave:''};level.events.push(o);selected={kind:'event',id:o.id}}refresh()};

