for(const [kind,label]of [['event','Events'],['item','Items']]){let lane=document.createElement('div');lane.className='lane';lane.innerHTML=`<label>${label}</label><div id="${kind}Track" class="track"></div>`;$('timeline').insertBefore(lane,$('playhead'))}$('timeline').style.height='255px';

